#!/usr/bin/env node
/**
 * beazt — IDE Project Generator
 * Usage in your IDE terminal (VS Code / Cursor / WebStorm):
 *   node import-beazt-project.js
 *
 * This script creates the complete `beazt-studio/` project folder
 * (index.html, css/styles.css, js/app.js, package.json, and all image/video assets).
 */
const fs = require('fs');
const path = require('path');

const FILES = {
  "index.html": "",
  "css/styles.css": "",
  "js/app.js": "",
  "package.json": "",
  "assets/images/slot-01.jpg": "",
  "assets/images/slot-02.jpg": "",
  "assets/images/slot-03.jpg": "",
  "assets/images/slot-04.jpg": "",
  "assets/images/slot-05.jpg": "",
  "assets/images/slot-06.jpg": "",
  "assets/video/showreel.mp4": ""
};

const targetRoot = path.join(process.cwd(), 'beazt-studio');
for (const [relPath, b64] of Object.entries(FILES)) {
  const fullPath = path.join(targetRoot, relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(b64, 'base64'));
  console.log('Created:', path.relative(process.cwd(), fullPath));
}
console.log('\n✓ Project ready in ./beazt-studio — open index.html with Live Server or run: npx serve beazt-studio');